import raw from "./image-meta.json"

/** Pixel size of an image, plus a tiny blurred copy to show while it loads. */
export interface ImageMeta {
  width: number
  height: number
  /** Base64 WebP no larger than 10px, for next/image's `placeholder="blur"`. */
  blurDataURL?: string
}

// Generated by scripts/generate-image-meta.mjs for every image in a public/
// subfolder. Typed as a record so any src string can index it.
const META: Record<string, ImageMeta | undefined> = raw

/**
 * Size and blur preview for a project image. Images hosted elsewhere carry their
 * own width and height in lib/projects.ts, since the build only reads public/.
 * Safe on the server and in the browser: it only reads the generated JSON.
 */
export function getImageMeta(image: { src: string; width?: number; height?: number }): ImageMeta | undefined {
  if (image.width && image.height) return { width: image.width, height: image.height }
  const meta = META[image.src]
  if (!meta && process.env.NODE_ENV === "development" && image.src.startsWith("/")) {
    console.warn(`No size for ${image.src}; run \`npm run images:meta\` after adding images to public/.`)
  }
  return meta
}

/** next/image can't resize animated GIFs, so they are served as they are. */
export function isGif(src: string): boolean {
  return src.toLowerCase().endsWith(".gif")
}
